\begin{ex}%[7H3N1]
\immini[thm]{
Cho hình vẽ sau. Biết $\widehat{O_{1}} =55^{\circ}$, tính số đo góc $\widehat{O_{2}}$.

\choice
{ $\widehat{O_{2} }=55^{\circ}$   }
   { \True $\widehat{O_{2} }=125^{\circ} $  }
     { $\widehat{O_{2} }=65^{\circ}$   }
    { $\widehat{O_{2} }=115^{\circ}$   }
}{
\begin{tikzpicture}
            % Vẽ các điểm A, B, C, D
            \coordinate (A) at (0, 0);
            \coordinate (B) at (4, 4);
            \coordinate (C) at (6, 0);
            \coordinate (D) at (2, -3);

            % Vẽ đường thẳng đi qua A và C
            \draw[thick] (A) -- (C);

            % Vẽ đường thẳng đi qua B và D
            \draw[thick] (B) -- (D) ;

            % Tìm giao điểm O của 2 đường thẳng
            \coordinate (O) at (intersection of A--C and B--D);

            % Đánh dấu các điểm A, B, C, D, O

            \fill (O) circle (2pt) node[above right] {O};
            \draw 
            (O)  node[shift={{(49:-15pt)}}]{{$1$}} 
            ;
            \draw 
            (O)  node[shift={{(-45:14pt)}}]{{$2$}} 
            ;
        \end{tikzpicture}
}
\loigiai{
Vì $\widehat{O_{1} }$ và $\widehat{O_{2} }$ là hai góc kề bù nên $\widehat{O_{2}}=180^{\circ}-\widehat{O_{1}} =125^{\circ}$
}\end{ex}

